# 01–10: tiny, authentic excerpts; surrounding classes/functions remain in the source view.
lesson('bear-001', 'bear-01', 'Ein Name für den Bären.', 'HomeUi hält den Namen fest. Ergänze das Schlüsselwort für eine Eigenschaft, die nicht neu zugewiesen werden kann.', (U, 'val bearName: String = "Bear"'), [g('val','Deklaration','val verhindert eine erneute Zuweisung.')], 'val im UI-Modell', 'HomeUi beschreibt Bears Startbildschirm. val benennt einen Wert ohne spätere Neuzuweisung. Die Zeile ist ein Konstruktorparameter; deshalb endet sie mit einem Komma. Das gesamte Objekt ist dadurch nicht automatisch tief unveränderlich.', [BASIC])
lesson('bear-002', 'bear-01', 'Bears Standardname.', 'Ergänze den String-Literal für den Standardnamen Bear, einschließlich Anführungszeichen.', (S, 'const val DEFAULT = "Bear"'), [g('"Bear"','Textwert','Strings stehen in doppelten Anführungszeichen.')], 'String-Literale', 'BearName.DEFAULT ist der Standard, bevor du einen eigenen Namen vergibst. Text braucht doppelte Anführungszeichen. Ohne sie würde Bear als Name eines Symbols gelesen. const macht diesen Wert zu einer Konstante zur Compile-Zeit.', [k('strings', 'String-Literale', 'declare-strings')])
lesson('bear-003', 'bear-01', 'Ein veränderlicher Merker.', 'SentenceMatcher merkt sich, ob zuletzt ein Leerraum verarbeitet wurde. Ergänze das Schlüsselwort, das spätere Neuzuweisungen erlaubt.', (M, 'var lastSpace = true'), [g('var','Veränderliche Variable','var erlaubt, später false zuzuweisen.')], 'var in einem Algorithmus', 'lastSpace verändert sich beim Durchlaufen des Texts. Hier ist var passend. Die Bedeutung des Werts bleibt Boolean, auch wenn er zwischen true und false wechselt. Im Dateikontext siehst du die späteren Zuweisungen.', [BASIC])
lesson('bear-004', 'bear-01', 'Ein Name hat einen Typ.', 'Ergänze den Kotlin-Typ für den Namen im HomeUi-Konstruktor.', (U, 'val bearName: String = "Bear"'), [g('String','Texttyp','Typnamen werden großgeschrieben.')], 'Typangaben', 'Nach dem Doppelpunkt steht der Typ. String ist eine Zeichenfolge; Char bezeichnet ein einzelnes Zeichen. Der Standardwert Bear wird verwendet, wenn beim Erstellen von HomeUi kein Name angegeben wird.', [k('strings')])
lesson('bear-005', 'bear-01', 'Noch nicht verbunden.', 'HomeUi soll standardmäßig keine Linear-Verbindung melden. Ergänze den booleschen Wert.', (U, 'val connected: Boolean = false'), [g('false','Wahrheitswert','Nicht verbunden bedeutet false, ohne Anführungszeichen.')], 'Boolean-Zustand', 'connected ist true oder false. Der Wert ist kein Text. Bear leitet den tatsächlichen Zustand später aus den gespeicherten Einstellungen ab; false ist nur der Startwert dieses Modells.', [k('booleans')])
lesson('bear-006', 'bear-01', 'Einträge zählen.', 'Ergänze den Ganzzahltyp für die Anzahl der Einträge auf dem Startbildschirm.', (U, 'val entryCount: Int = 0'), [g('Int','Ganzzahltyp','Int ist der übliche 32-Bit-Ganzzahltyp.')], 'Int', 'entryCount zählt Gedanken und Themen. Int speichert ganze Zahlen; 0 ist der Startwert. Kotlin kann Typen oft ableiten, aber an Modellgrenzen steht der Typ hier explizit.', [k('numbers', 'Ganzzahlen: Int und Long', 'integer-types')])
lesson('bear-007', 'bear-01', 'Zeitstempel brauchen Platz.', 'ThoughtEntity speichert createdAt als Millisekunden-Zeitstempel. Ergänze den verwendeten 64-Bit-Ganzzahltyp.', (D, 'val createdAt: Long'), [g('Long','Zeitstempeltyp','Long bietet einen größeren Wertebereich als Int.')], 'Long für Zeitstempel', 'Millisekunden seit 1970 passen heute nicht mehr in einen Int. Bear verwendet deshalb Long. Die Einheit ist eine Vereinbarung des Codes: Long allein unterscheidet nicht zwischen Millisekunden und Tagen.', [k('numbers', 'Ganzzahlen: Int und Long', 'integer-types')])
lesson('bear-008', 'bear-01', 'Ein nächster Schritt darf fehlen.', 'BearBlock erlaubt einen fehlenden Schritt. Ergänze den vollständigen Texttyp einschließlich Nullbarkeit.', (B, 'val step: String? = null'), [g('String?','Optionaler Text','Ein Fragezeichen nach String erlaubt null.')], 'Nullable-Typen', 'String? erlaubt Text oder null. null bedeutet hier: kein Schritt gespeichert. Ein leerer String ist dagegen ein vorhandener Text mit null Zeichen. Der Unterschied ist für Parser und Darstellung relevant.', [k('null-safety', 'Nullable-Typen', 'nullable-types-and-non-nullable-types')])
lesson('bear-009', 'bear-01', 'Bears feste Obergrenze.', 'BearName begrenzt Namen auf 20 Zeichen. Ergänze den Modifikator für eine Compile-Zeit-Konstante.', (S, 'const val MAX_LENGTH = 20'), [g('const','Konstanten-Modifikator','const steht vor val; der Name verwendet Großbuchstaben und Unterstriche.')], 'Konstanten benennen', 'MAX_LENGTH ist ein einfacher, zur Compile-Zeit bekannter Int. const val darf unter anderem in einem object stehen. Der Name in Großbuchstaben mit Unterstrichen macht die Konstante erkennbar.', [k('properties', 'Compile-Zeit-Konstanten', 'compile-time-constants'), k('coding-conventions')])
lesson('bear-010', 'bear-01', 'Die Linear-Kennung im Text.', 'Ergänze das String-Template, das row.identifier in Bears Statuszeile einsetzt. Gib auch Dollarzeichen und geschweifte Klammern ein.', (U, 'ThoughtState.InLinear -> "In Linear als ${row.identifier}"'), [g('${row.identifier}','String-Template','Für einen Eigenschaftszugriff im String verwendest du ${…}.')], 'String-Templates', 'Die Zeile ist ein Zweig aus Words.thoughtState. ${row.identifier} wertet den Eigenschaftszugriff aus und setzt ihn in den Text ein. Die äußeren Anführungszeichen gehören bereits zum sichtbaren Code.', [k('strings', 'String-Templates', 'string-templates')])

# 11–20: language mechanics in actual domain code.
lesson('bear-011', 'bear-02', 'Bear begrüßt dich.', 'Ergänze das Schlüsselwort zur Deklaration der Funktion greeting.', (U, 'fun greeting(', '\n    }'), [g('fun','Funktion','Funktionen werden mit fun deklariert.')], 'Funktionen und Rückgabe', 'Words.greeting nimmt einen Zeitpunkt und liefert einen String. Nach = folgt ein Ausdruck, dessen Wert zurückgegeben wird. Der Standardparameter ZonedDateTime.now() wird ausgewertet, wenn der Aufruf keinen Zeitpunkt übergibt.', [FUN])
lesson('bear-012', 'bear-02', 'Morgens, mittags, abends.', 'Ergänze die Fallunterscheidung in greeting. Die erste passende Stunde bestimmt den Text.', (U, 'fun greeting(', '\n    }'), [g('when','Fallunterscheidung','when prüft seine Zweige der Reihe nach.')], 'when-Ausdrücke', 'Bear ordnet Stunden Bereichen zu. Die Bereiche mit .. enthalten beide Grenzen. else behandelt alle übrigen Stunden. Der gesamte when-Ausdruck liefert den String der Begrüßung.', [k('control-flow', 'when-Ausdrücke', 'when-expressions-and-statements')])
lesson('bear-013', 'bear-02', 'Ein Bereich für den Rhythmus.', 'Ergänze den inklusiven Bereich für Rhythm.Normal: drei bis sieben Tage.', (P, 'Normal("normal", 3..7)'), [g('3..7','Tagebereich','Der Operator .. schließt beide Grenzen ein.')], 'IntRange', 'Rhythm.Normal enthält einen IntRange. 3..7 umfasst 3, 4, 5, 6 und 7. Ein Bereich ist noch keine Zufallsauswahl; RoundPlanner entscheidet später über den konkreten Tag.', [k('ranges')])
lesson('bear-014', 'bear-02', 'Leere Texte ablehnen.', 'matches darf leere normalisierte Eingaben nicht akzeptieren. Ergänze die Rückgabe im frühen Abbruch.', (M, 'fun matches(', '\n    }'), [g('return false','Frühe Rückgabe','return beendet diese Funktion mit dem angegebenen Boolean.')], 'Guard Clauses', 'Vor dem Distanzvergleich prüft SentenceMatcher einen einfachen Ausschlussgrund. Der frühe return hält den übrigen Pfad übersichtlich. Die Funktion liefert Boolean, also muss auch dieser Ausgang einen Boolean zurückgeben.', [k('returns')])
lesson('bear-015', 'bear-02', 'Toleranz mit einer Bedingung.', 'Bei weniger als zwölf normalisierten Zeichen ist die Fehlertoleranz null. Ergänze den Vergleichsoperator.', (M, 'fun tolerance(', '\n    }'), [g('<','Vergleich','Die Grenze 12 selbst gehört nicht zum kleineren Bereich.')], 'if als Ausdruck', 'Die Funktion liefert entweder 0 oder maxOf(1, n / 20). n und 20 sind Int-Werte: Die Division verwirft einen Rest. Das ist die konkrete Heuristik dieses Bear-Stands, keine allgemeine Regel für Texteingaben.', [k('control-flow', 'if als Ausdruck', 'if-expression'), k('numbers')])
lesson('bear-016', 'bear-02', 'Wann ein Thema feststeckt.', 'stuck gilt nur außerhalb der aktuellen Runde UND nach genügend unbeantworteten Runden. Ergänze den UND-Operator.', (D, 'val stuck: Boolean get()'), [g('&&','Logisches UND','Beide Seiten müssen wahr sein.')], 'Berechnete Eigenschaften', 'stuck speichert keinen separaten Boolean. Sein Getter berechnet ihn aus inRound und unhandledRounds. ! negiert inRound, >= vergleicht mit der Schwelle. && verbindet beide Anforderungen.', [k('properties', 'Getter und Setter', 'custom-getters-and-setters'), k('booleans')])
lesson('bear-017', 'bear-02', 'Benachrichtigungen nur bei Bedarf.', 'Der Onboarding-Schritt soll gelten, wenn Benachrichtigungen noch nicht an sind. Ergänze den Negationsoperator.', (O, 'OnboardingStep.Notifications -> !facts.notificationsOn'), [g('!','Negation','! kehrt einen Boolean um.')], 'Ein Boolean wird umgedreht', 'OnboardingFlow.applies entscheidet über die Relevanz eines Schritts. facts.notificationsOn ist bereits ein Boolean. ! bedeutet nicht. Ein Vergleich mit false wäre ebenfalls ein Kotlin-Ausdruck, hier rekonstruierst du den Originaloperator.', [k('booleans')])
lesson('bear-018', 'bear-02', 'Ein Thema braucht eine Herkunft.', 'Der Themen-Schritt gilt mit Linear-Verbindung ODER mit einem lokal erfassten Gedanken. Ergänze den ODER-Operator.', (O, 'OnboardingStep.Topic -> facts.connected || facts.hasThought'), [g('||','Logisches ODER','Mindestens eine Seite muss wahr sein.')], 'Kurzschlussauswertung', '|| ist wahr, sobald die linke Seite wahr ist; dann wird die rechte Seite nicht mehr benötigt. In Bear reicht hier eine der beiden möglichen Grundlagen für ein Thema.', [k('booleans')])
lesson('bear-019', 'bear-02', 'Argumente beim Namen nennen.', 'Ergänze den Namen des Parameters, der in RoundSelection.Update auf false gesetzt wird.', (R, 'updates += Update(t.id, inRound = false, unhandledRounds = unhandled)'), [g('inRound','Benanntes Argument','Die Eigenschaft steuert, ob ein Thema in der Runde liegt.')], 'Benannte Argumente', 'Bei mehreren ähnlichen Werten verbessern Namen die Lesbarkeit. inRound = false ist ein benanntes Argument beim Konstruktoraufruf. Das äußere += fügt das entstandene Update zur veränderlichen Liste hinzu.', [k('functions', 'Benannte Argumente', 'named-arguments')])
lesson('bear-020', 'bear-02', 'Eine Funktion erweitern.', 'Die Hilfsfunktion hhmm erweitert LocalTime. Ergänze den Empfängertyp vor dem Punkt.', (P, 'private fun LocalTime.hhmm()'), [g('LocalTime','Extension-Empfänger','Der Typ steht vor dem Punkt und dem Funktionsnamen.')], 'Extension-Funktionen', 'Mit LocalTime.hhmm wird ein Aufruf wie start.hhmm() möglich. Die Funktion kann hour und minute des Empfängers verwenden. Sie verändert die Java-Klasse nicht. private begrenzt diese Top-Level-Funktion auf ihre Kotlin-Datei.', [k('extensions'), k('visibility-modifiers')])

# 21–30: models and safe access; two gaps become normal.
lesson('bear-021', 'bear-03', 'Der Bear-Block als Modell.', 'Ergänze den Modifikator für eine Datenklasse und den Typ ihrer Satzliste.', (B, 'data class BearBlock(', ') {'), [g('data','Datenklasse','data generiert unter anderem copy und Wertgleichheit.'),g('List<String>','Satzliste','Eine List mit String als Elementtyp.')], 'Datenklassen', 'BearBlock bündelt Sätze, nächsten Schritt, Intervall und unbekannte Zusatzzeilen. data generiert unter anderem equals und copy anhand der Eigenschaften im primären Konstruktor. Eine List-Schnittstelle ist nur lesbar, nicht automatisch tief unveränderlich.', [k('data-classes'), k('collections-overview')])
lesson('bear-022', 'bear-03', 'Ein Singleton für die Regeln.', 'RoundSelection braucht keine eigene Instanz pro Aufruf. Ergänze die Deklaration des Singleton-Objekts.', (R, 'object RoundSelection {', 'const val STUCK_AFTER'), [g('object','Singleton','object deklariert eine einzelne Instanz.')], 'object', 'RoundSelection sammelt zustandslose Auswahlregeln und Konstanten. object stellt eine einzelne Instanz bereit. Ein Aufruf lautet deshalb RoundSelection.pick(...), ohne vorher RoundSelection() aufzurufen.', [k('object-declarations')])
lesson('bear-023', 'bear-03', 'Endlich viele Zustände.', 'Ergänze die zwei Wörter, mit denen Bear die festgelegten Übertragungszustände deklariert.', (D, 'enum class ThoughtState'), [g('enum class','Aufzählung','enum class definiert eine Menge benannter Werte.')], 'Enums', 'Ein Gedanke ist Local, Sending, InLinear oder NeedsAttention. Ein enum bildet genau diese benannten Werte ab. Der Typ verhindert, dass beliebige Textwerte als Übertragungszustand dienen.', [k('enum-classes')])
lesson('bear-024', 'bear-03', 'Die Runde lädt noch.', 'Ergänze die kontrollierte Interface-Hierarchie und die Datenklasse für eine sichtbare Runde.', (U, 'sealed interface RoundState', '\n}'), [g('sealed interface','Zustandsfamilie','sealed interface erlaubt dem Compiler, bekannte Untertypen zu berücksichtigen.'),g('data class','Zustand mit Nutzdaten','Show trägt zusätzlich ein RoundUi.')], 'Sealed-Zustände', 'Loading, None und Show sind verschiedene Fälle. Show trägt UI-Daten, die anderen nicht. Eine sealed-Hierarchie ermöglicht eine vollständige Fallunterscheidung. Diese Trennung verhindert in Bear, dass ein anfänglich leerer Speicher schon als fertiges Ergebnis erscheint.', [k('sealed-classes')])
lesson('bear-025', 'bear-03', 'Sicher auf einen Match zugreifen.', 'Der Regex kann nichts finden. Ergänze beide Safe-Call-Operatoren vor groupValues und get.', (B, 'val a = m?.groupValues?.get(1)?.toIntOrNull()'), [g('?.','Erster Safe Call','m kann null sein.',occurrence=1),g('?.','Zweiter Safe Call','Die Kette muss bei null weiter sicher bleiben.',occurrence=2)], 'Safe Calls in einer Kette', 'Ein Safe Call liefert null, wenn sein Empfänger null ist. toIntOrNull behandelt außerdem nicht parsebare Zahlen. a ist dadurch Int?, was die folgende Bedingung berücksichtigt.', [k('null-safety', 'Safe Calls', 'safe-call-operator')])
lesson('bear-026', 'bear-03', 'Ein Ersatzintervall.', 'effectiveDays verwendet ein eigenes Intervall, falls vorhanden, sonst rhythm.days. Ergänze den Operator.', (P, 'val base = override ?: rhythm.days'), [g('?:','Ersatz bei null','Der Elvis-Operator wählt rechts nur bei null.')], 'Elvis-Operator', 'override ist hier ein Parametername und ein weiches Kotlin-Schlüsselwort. ?: liefert den linken Wert, sofern er nicht null ist. Ein leeres oder ungültiges Intervall würde dadurch nicht automatisch repariert.', [k('null-safety', 'Elvis-Operator', 'elvis-operator')])
lesson('bear-027', 'bear-03', 'Ohne Beschreibung abbrechen.', 'BearBlock.find muss bei fehlender Beschreibung oder fehlendem Zaun null liefern. Ergänze die beiden frühen Rückgaben.', (B, 'fun find(description:', '\n        }'), [g('return null','Keine Beschreibung','Die Funktion liefert Found?; null ist erlaubt.',occurrence=1),g('return null','Kein Bear-Block','Auch rechts von ?: kann return stehen.',occurrence=2)], 'Nullable-Rückgaben', 'Found? modelliert, dass eine Beschreibung keinen Bear-Block enthalten muss. Die frühen Rückgaben verhindern spätere Zugriffe ohne Match. Das ist ein normaler Ergebnisfall, keine Exception.', [NULL, k('returns')])
lesson('bear-028', 'bear-03', 'Nur vorhandene Schritte schreiben.', 'render soll einen Schritt nur bei vorhandenem Wert ausgeben. Ergänze die Scope-Funktion und ihren impliziten Parameter.', (B, 'step?.let { appendLine("Schritt: $it") }'), [g('let','Scope-Funktion','?. überspringt den Block bei null; let übergibt den vorhandenen Wert.'),g('$it','Wert im Template','Der einzelne Lambda-Parameter heißt implizit it.')], 'let und it', 'let ruft einen Block mit dem Empfänger als Argument auf. Erst ?. sorgt dafür, dass der Aufruf bei null entfällt. Im String reicht $it, weil nur eine einfache Variable eingesetzt wird.', [k('scope-functions', 'let und it', 'let'), k('strings')])
lesson('bear-029', 'bear-03', 'Eine Kopie mit neuem Text.', 'ThoughtRepository aktualisiert den Text eines Gedanken über eine neue Dateninstanz. Ergänze Methode und benanntes Argument.', (Q, 'db.thoughts().upsert(t.copy(text = text))'), [g('copy','Kopiermethode','data class generiert copy.'),g('text','Parametername','Links vom = steht die Eigenschaft, rechts der lokale neue Text.',within='text = text')], 'copy statt Mutation', 't bleibt als Objekt unverändert. copy erzeugt eine flache Kopie und ersetzt text. upsert schreibt die neue Instanz in Room. Die beiden text-Vorkommen haben unterschiedliche Rollen: Argumentname und lokaler Wert.', [k('data-classes', 'Kopieren mit copy', 'copying'), ROOM])
lesson('bear-030', 'bear-03', 'Optional in der Datenbank suchen.', 'ThoughtDao.get kann keinen Gedanken finden. Ergänze suspend und den nullable Rückgabetyp.', (D, 'suspend fun get(id: String): ThoughtEntity?'), [g('suspend','Suspendierbare Funktion','Room unterstützt suspendierende Einzelabfragen.'),g('ThoughtEntity?','Optionales Ergebnis','Ein fehlender Datensatz wird durch null dargestellt.')], 'Ein Datenbankzugriff mit klarer Grenze', 'Die DAO-Methode beschreibt einen suspendierenden Zugriff. suspend alleine bedeutet nicht automatisch Hintergrundthread; Room stellt hier die Implementierung bereit. ThoughtEntity? zwingt Aufrufer dazu, einen nicht gefundenen Gedanken zu behandeln.', [ROOM, CORO])

# 31–40: the domain's real collection and parser idioms.
lesson('bear-031', 'bear-04', 'Nur wartende Themen.', 'Ergänze die Listenoperation und das Prädikat, um Themen in der aktuellen Runde auszuwählen.', (R, 'val waiting = topics.filter { it.inRound }'), [g('filter','Listenoperation','filter behält Elemente mit wahrem Prädikat.'),g('it.inRound','Prädikat','it ist das aktuelle RoundCandidate.')], 'filter mit einer Lambda', 'Die neue Liste enthält genau die passenden Kandidaten. topics wird nicht verändert. Die geschweiften Klammern sind eine Lambda; als letztes Argument darf sie hinter den Aufrufklammern stehen.', [k('collection-filtering'), LAMBDA])
lesson('bear-032', 'bear-04', 'Aus Themen werden IDs.', 'Ergänze die Umwandlung und den Eigenschaftszugriff in entriesInOrder.', (U, 'val topicIds = topics.map { it.issueId }.toSet()'), [g('map','Umwandlung','map erzeugt pro Eingabeelement einen Ausgabewert.'),g('it.issueId','ID eines Themas','Die Linear-ID heißt issueId.')], 'map und Set', 'map projiziert jedes Thema auf seine ID. toSet entfernt Duplikate und ermöglicht die anschließende Mitgliedschaftsprüfung. Dadurch zeigt Bear einen Gedanken nicht zusätzlich an, wenn dieselbe ID schon ein Thema bezeichnet.', [k('collection-transformations'), k('collections-overview')])
lesson('bear-033', 'bear-04', 'Doppelte Einträge vermeiden.', 'Ergänze den Operator, der Gedanken mit bereits vorhandener Themen-ID ausfiltert.', (U, 'return topics.sortedWith(order) to thoughts.filter { it.id !in topicIds }'), [g('!in','Nicht enthalten','in prüft Mitgliedschaft, !in deren Gegenteil.')], 'Mitgliedschaft und Pair', 'Der Ausdruck liefert ein Pair: links sortierte Themen, rechts übrige Gedanken. to ist eine infix-Funktion. Der Filter sorgt dafür, dass die gemeinsame Eintragsansicht dieselbe Sache nicht doppelt zeigt.', [k('collection-filtering'), FUN])
lesson('bear-034', 'bear-04', 'Die ältesten Fälligkeiten zuerst.', 'Ergänze den Vergleichsaufbau und seine beiden Sortierschlüssel in der Originalreihenfolge.', (R, 'private val order = compareBy'), [g('compareBy<RoundCandidate>','Comparator','compareBy ist hier generisch für RoundCandidate.'),g('{ it.nextDue }, { it.id }','Sortierschlüssel','Erst Fälligkeit, dann ID als stabiler Gleichstandsauflöser.')], 'Mehrstufige Sortierung', 'compareBy erstellt einen Comparator aus mehreren Schlüsseln. Die zweite Regel wird nur bei Gleichstand der ersten benötigt. Eine feste Reihenfolge macht Bears Auswahl reproduzierbarer und Tests verständlicher.', [k('collection-ordering')])
lesson('bear-035', 'bear-04', 'Zeitfenster vereinheitlichen.', 'Ergänze die Operationen zum Sortieren, zum Entfernen gleicher Tagesabschnitte und zum Begrenzen der Anzahl.', (P, 'fun normalize(windows:', 'windows.sortedBy'), [g('sortedBy','Sortieren','Sortiere nach start.'),g('distinctBy','Eindeutige Tagesabschnitte','Behalte je part nur das erste Fenster.'),g('take','Obergrenze','Nimm höchstens MAX_WINDOWS Elemente.')], 'Eine Pipeline aus Listenoperationen', 'Die Reihenfolge ist relevant: Erst nach Startzeit sortieren, dann je Tagesabschnitt eines behalten, danach begrenzen. Jede Operation liefert die Eingabe für die nächste. Die Pipeline ändert die ursprüngliche Liste nicht.', [k('collection-ordering'), k('collection-filtering')])
lesson('bear-036', 'bear-04', 'Defekte gespeicherte Fenster verwerfen.', 'Ergänze die Listenoperation und den Result-Zugriff, damit fehlerhafte Einträge wegfallen.', (P, 'fun parseList(text:', '\n        }'), [g('mapNotNull','Parsen und Filtern','mapNotNull entfernt null-Ergebnisse.'),g('getOrNull','Fehler als fehlender Wert','runCatching liefert Result; bei Fehler soll null entstehen.')], 'mapNotNull und runCatching', 'Jeder gespeicherte Textteil wird unabhängig geparst. runCatching kapselt eine Exception als Result. getOrNull macht den Fehlversuch zu null; mapNotNull entfernt ihn. Wenn nichts übrig bleibt, verwendet Bear das Abendfenster.', [k('collection-transformations'), k('exceptions')])
lesson('bear-037', 'bear-04', 'Leerzeilen im Bear-Block.', 'Ergänze den Rücksprung, der nur die aktuelle forEachIndexed-Lambda beendet.', (B, 'content.lines().forEachIndexed', 'if (line.isEmpty())'), [g('return@forEachIndexed','Lokaler Rücksprung','Ein return mit Label beendet hier nur den aktuellen Lambda-Aufruf.')], 'Labelled Returns', 'Ein blankes return würde bei dieser Inline-Funktion den Parser verlassen. return@forEachIndexed überspringt nur die aktuelle Leerzeile. Der nächste Listeneintrag wird weiter verarbeitet.', [k('returns', 'Rückgaben mit Labels', 'return-to-labels')])
lesson('bear-038', 'bear-04', 'Schlüssel und Wert trennen.', 'Rekonstruiere die beiden Ausdrücke hinter substring: Schlüssel bis zum Doppelpunkt, Wert danach.', (B, 'val key = line.substring', 'val value = line.substring'), [g('0, colon','Schlüsselbereich','Die Endposition von substring ist exklusiv.'),g('colon + 1','Beginn des Werts','Der Doppelpunkt selbst gehört nicht zum Wert.')], 'String-Grenzen', 'Der Parser sucht zuvor den ersten Doppelpunkt. trim entfernt Rand-Leerraum; lowercase macht nur den Schlüssel unabhängig von Großschreibung. Der Wert wird nicht kleingeschrieben, damit Stevens Text erhalten bleibt.', [k('strings')])
lesson('bear-039', 'bear-04', 'Ein val kann eine veränderliche Liste halten.', 'Ergänze den Erzeuger der Satzliste und das Elementtypargument.', (B, 'val sentences = mutableListOf<String>()'), [g('mutableListOf','Veränderliche Liste','Die Referenz bleibt, der Inhalt kann wachsen.'),g('String','Elementtyp','Jeder Satz ist Text.')], 'Referenz und Inhalt unterscheiden', 'val verhindert nur eine neue Zuweisung an sentences. mutableListOf erzeugt eine Liste, deren Inhalt geändert werden kann. Bear fügt während des Parsens weitere Sätze hinzu. Das ist kein Widerspruch zu val.', [k('collections-overview')])
lesson('bear-040', 'bear-04', 'Den Bear-Block rendern.', 'Ergänze den String-Builder, die Iteration der Sätze und das Entfernen abschließender Leerzeichen.', (B, 'fun render():', '}.trimEnd()'), [g('buildString','String aufbauen','Im Block stehen StringBuilder-Funktionen bereit.'),g('forEach','Sätze durchlaufen','Jeder Satz bekommt eine eigene Zeile.',occurrence=1),g('trimEnd','Ende bereinigen','Am Ende soll kein zusätzlicher Zeilenumbruch bleiben.')], 'Builder-Lambda mit Empfänger', 'buildString stellt einen StringBuilder als Empfänger bereit. appendLine braucht deshalb keinen expliziten Empfängernamen. Sichere Zugriffe überspringen fehlenden Schritt und Abstand; unbekannte Zusatzzeilen werden wieder ausgegeben.', [k('lambdas'), k('strings')])

# 41–50: Android conventions and Compose syntax, using the actual UI.
lesson('bear-041', 'bear-05', 'Bears Einstiegspunkt.', 'Ergänze das Vererbungszeichen und den Aufruf des Basisklassen-Konstruktors.', (A, 'class MainActivity : ComponentActivity() {'), [g(':','Vererbung','Kotlin verwendet einen Doppelpunkt.'),g('ComponentActivity()','Basisklassen-Konstruktor','Der Klassenname wird großgeschrieben, der Konstruktor mit () aufgerufen.')], 'Klasse und Basisklasse', 'MainActivity ist ein Android-Einstiegspunkt. ComponentActivity liefert die Integration, auf der die Compose-Activity aufbaut. Dateiname und Klassenname folgen hier derselben UpperCamelCase-Schreibweise.', [k('inheritance'), k('coding-conventions')])
lesson('bear-042', 'bear-05', 'Eine Lifecycle-Methode überschreiben.', 'Ergänze override und den Aufruf der Basisklassen-Methode. Die restlichen Bear-Details kannst du zunächst mitlesen.', (A, 'override fun onCreate(', '\n    }'), [g('override','Überschreiben','override macht das Überschreiben explizit.'),g('super.onCreate(savedInstanceState)','Basisklassen-Aufruf','Rufe dieselbe Methode auf super mit dem Bundle auf.')], 'onCreate', 'onCreate richtet eine Activity-Instanz ein. Bear prüft dort Start-Intents und baut die Oberfläche auf. savedInstanceState unterscheidet unter anderem einen frischen Start von Wiederherstellung. Die Instanz kann später neu entstehen.', [a('guide/components/activities/activity-lifecycle','Activity-Lebenszyklus')])
lesson('bear-043', 'bear-05', 'Bears Compose-Baum starten.', 'Ergänze die Funktion, die den Compose-Inhalt der Activity setzt, und Bears Theme-Composable.', (A, 'setContent { BearTheme { BearAppUi'), [g('setContent','Compose-Inhalt setzen','setContent gehört zur Activity-Compose-Integration.'),g('BearTheme','App-Theme','BearTheme umschließt den eigentlichen App-Inhalt.')], 'Verschachtelte Composable-Aufrufe', 'Die Lambdas beschreiben einen UI-Baum: setContent startet ihn, BearTheme stellt Gestaltung bereit, BearAppUi wählt den Inhalt. Das sind echte Funktionsaufrufe mit nachgestellten Lambdas, keine besondere Markup-Sprache.', [a('develop/ui/compose/mental-model','Compose-Modell'), LAMBDA])
lesson('bear-044', 'bear-05', 'Eine Oberfläche deklarieren.', 'Ergänze die Annotation und den Callback-Typ für einen Text, den QuickCaptureRoute an den Aufrufer meldet.', (C, '@Composable\nfun QuickCaptureRoute', 'var draft by remember'), [g('@Composable','Compose-Annotation','Die Annotation beginnt mit @.'),g('(String) -> Unit','Text-Callback','Eine Funktion mit String-Parameter ohne nutzbaren Rückgabewert.')], 'Composable-Namen und Funktionstypen', 'QuickCaptureRoute liefert UI und hat Unit als Rückgabe; solche Composables beginnen groß. onSave ist eine Funktion als Parameter. (String) -> Unit beschreibt ihre Signatur, nicht ihren unmittelbaren Aufruf.', [k('coding-conventions'), LAMBDA])
lesson('bear-045', 'bear-05', 'Ein Textentwurf in Compose.', 'Ergänze die Delegation, den Cache und den beobachtbaren Zustand.', (C, 'var draft by remember { mutableStateOf("") }'), [g('by','Delegation','by verwendet getValue und setValue.'),g('remember','Über Recomposition behalten','remember hält das Objekt an dieser Stelle in der Composition.'),g('mutableStateOf','Beobachtbarer Zustand','Änderungen dieses State können Recomposition auslösen.')], 'remember und by', 'draft lässt sich dank Delegation wie ein String lesen und schreiben. remember erhält das State-Objekt über Recompositions, nicht über jede Activity-Neuerstellung. Die nötigen Imports stehen in der Originaldatei.', [STATE, k('delegated-properties')])
lesson('bear-046', 'bear-05', 'Der Entwurf überlebt eine Drehung.', 'HomeRoute verwendet die speicherbare Variante. Ergänze sie und den leeren String-Literal.', (H, 'var draft by rememberSaveable { mutableStateOf("") }'), [g('rememberSaveable','UI-Wiederherstellung','Diese Variante nutzt den Saved-State-Mechanismus.'),g('""','Leerer Startwert','Ein leerer String besteht aus zwei doppelten Anführungszeichen.')], 'rememberSaveable', 'Der Entwurf auf Bears Startseite ist kleiner UI-Zustand. rememberSaveable unterstützt seine Wiederherstellung nach einer Activity-Neuerstellung und systembedingtem Prozessverlust. Es ersetzt nicht die dauerhafte Speicherung eines abgesendeten Gedanken.', [a('develop/ui/compose/state-saving','UI-Zustand speichern')])
lesson('bear-047', 'bear-05', 'Ein Bear-Text mit Abstand.', 'Ergänze das Text-Composable und die vollständige Modifier-Kette für Breite und vertikalen Abstand.', (C, 'Text(\n                    "Liegt sicher bei mir."', '\n                )'), [g('Text','Text anzeigen','Text gehört zu Compose, println würde in die Konsole schreiben.'),g('Modifier.fillMaxWidth().padding(vertical = 18.dp)','Layout-Kette','Volle Breite, danach vertikal 18 dp Padding.')], 'Modifier und benannte Dimensionen', 'Modifier beschreibt Eigenschaften wie Größe und Abstand. dp ist dichteunabhängig; vertical ist ein benanntes Argument. Bear verwendet außerdem Textstil und Tintenfarbe aus seinem Theme.', [a('develop/ui/compose/modifiers','Modifier')])
lesson('bear-048', 'bear-05', 'Callback weiterreichen.', 'Der Eingabetext und Änderungen sollen durchgereicht werden. Ergänze value und onValueChange in Bears echtem Textfeldaufruf.', (C, 'BearTextField(\n                    value = draft', '\n                )'), [g('draft','Aktueller Text','Das Kind erhält den aktuellen Wert.',within='value = draft'),g('onDraft','Änderungs-Callback','Übergib die Funktion selbst, ohne sie hier aufzurufen.',within='onValueChange = onDraft')], 'State Hoisting', 'QuickCaptureContent besitzt den Text nicht selbst. Es erhält draft und meldet Änderungen über onDraft. Das ist die Trennung zwischen Zustandseigentümer und darstellendem Composable. Der Callback wird erst beim Eingabeereignis ausgeführt.', [a('develop/ui/compose/state-hoisting','State Hoisting')])
lesson('bear-049', 'bear-05', 'Die IME-Sendetaste.', 'Ergänze die Tastaturaktion und den Callback-Aufruf, der darauf reagieren soll.', (C, 'keyboardActions = KeyboardActions'), [g('onSend','IME-Aktion','Die KeyboardOptions darüber wählen ImeAction.Send.'),g('onSave()','Callback ausführen','Innerhalb der Ereignis-Lambda wird die Funktion aufgerufen.')], 'Funktion übergeben oder aufrufen', 'onSave als Wert reicht eine Funktion weiter. onSave() führt sie aus. Hier steht der Aufruf im Ereignisblock, deshalb läuft er erst bei der IME-Aktion. Die benutzerdefinierte Komponente muss die KeyboardActions weiterverwenden.', [a('develop/ui/compose/text/user-input','Texteingaben'), LAMBDA])
lesson('bear-050', 'bear-05', 'Bears Stimmung aus dem Entwurf.', 'Rekonstruiere die drei Ergebnisse dieser when-Auswahl in QuickCaptureContent.', (C, 'BearFigure(\n            when {', '\n        )'), [g('BearMood.LegtAb','Nach dem Speichern','Gespeichert: der Bär legt den Zettel ab.'),g('BearMood.HoertZu','Während der Eingabe','Ein nicht leerer Entwurf lässt den Bären zuhören.'),g('BearMood.Ruhig','Sonst','Ohne beide Bedingungen bleibt er ruhig.')], 'UI aus Zustand ableiten', 'Die Stimmung wird aus saved und draft berechnet. Der erste passende Zweig gewinnt; saved hat Vorrang. Die Darstellung folgt diesem Wert, statt unabhängig einen zweiten Stimmungszustand zu pflegen.', [k('control-flow'), a('develop/ui/compose/mental-model','Deklarative UI')])

# 51–60: state ownership, effects and the actual ViewModel.
lesson('bear-051', 'bear-06', 'Ein Effekt nach dem Speichern.', 'Rekonstruiere die Effekt-API, die Verzögerung und den abschließenden Callback. Der Schlüssel saved bleibt sichtbar.', (C, 'LaunchedEffect(saved)'), [g('LaunchedEffect','Effekt','Ein geänderter Schlüssel startet die Effekt-Coroutine neu.'),g('delay(1300)','Suspendierendes Warten','delay wartet 1300 Millisekunden, ohne einen Thread zu blockieren.'),g('onDone()','Abschluss melden','Rufe nach dem Warten den Callback auf.')], 'LaunchedEffect und Lebensdauer', 'QuickCaptureRoute zeigt nach saved kurz die Bestätigung. LaunchedEffect ist an die Composition gebunden und wird beim Verlassen abgebrochen. saved wird hier direkt nach dem onSave-Aufruf gesetzt; das beweist für sich allein noch keinen abgeschlossenen Datenbank-Write.', [a('develop/ui/compose/side-effects','Compose-Effekte'), CORO])
lesson('bear-052', 'bear-06', 'Einen Flow im UI beobachten.', 'Ergänze die Lifecycle-bewusste Flow-Sammlung und die Kotlin-Delegation.', (A, 'val home by vm.home.collectAsStateWithLifecycle()'), [g('by','State delegieren','by liest hier den State-Wert.'),g('collectAsStateWithLifecycle','Flow zu Compose-State','Die Android-API berücksichtigt den UI-Lifecycle.')], 'Flow und Android-Lifecycle', 'vm.home liefert StateFlow<HomeUi>. collectAsStateWithLifecycle stellt Compose-State bereit und sammelt standardmäßig ab STARTED. Die Delegation erlaubt anschließend direkten Zugriff auf HomeUi statt auf State.value.', [STATE, FLOW])
lesson('bear-053', 'bear-06', 'Bears ViewModel konstruieren.', 'Ergänze die privat gehaltene Abhängigkeit und die Basisklasse.', (V, 'class BearViewModel(private val c: AppContainer) : ViewModel()'), [g('private val','Container nur intern','Der Konstruktorparameter wird eine private Eigenschaft.'),g('ViewModel()','Basisklasse','Rufe den Konstruktor von ViewModel auf.')], 'Explizite Abhängigkeiten', 'BearViewModel erhält AppContainer von außen. private verbirgt c vor Aufrufern. Android verwaltet das ViewModel über eine Factory; das ermöglicht eine längere Lebensdauer als die einer einzelnen Activity-Instanz.', [a('topic/libraries/architecture/viewmodel','ViewModel'), k('visibility-modifiers')])
lesson('bear-054', 'bear-06', 'Aus Einstellungen wird StateFlow.', 'Ergänze den Rückgabetyp, den Coroutine-Scope und den Startwert dieser stateIn-Konvertierung.', (V, 'val settings: StateFlow<BearSettings>'), [g('StateFlow<BearSettings>','Öffentlicher Zustand','Der aktuelle Zustand hat den Typ BearSettings.'),g('viewModelScope','Lebensdauer','Der Scope gehört zum ViewModel.'),g('BearSettings()','Startwert','Das Modell hat passende Standardwerte.')], 'stateIn', 'stateIn teilt einen Flow und stellt einen aktuellen Wert bereit. Dieser Bear-Stand verwendet SharingStarted.Eagerly: Das Sammeln startet sofort. Das ist die vorhandene Implementierung, keine universelle Empfehlung für jeden Flow.', [FLOW, CORO])
lesson('bear-055', 'bear-06', 'Zwei Datenströme verbinden.', 'Baue den Eintragszustand aus Themen und Gedanken: ergänze combine, die Build-Funktion und den Startwert.', (V, 'val entries: StateFlow<EntriesUi>', '.stateIn(viewModelScope, SharingStarted.Eagerly, EntriesUi())'), [g('combine','Flows kombinieren','combine arbeitet mit den jeweils neuesten Werten.'),g('buildEntries(t, th)','UI-Modell bauen','Reiche Themen und Gedanken in derselben Reihenfolge weiter.'),g('EntriesUi()','Leerer Startzustand','Der Startwert gehört zum Typ EntriesUi.')], 'combine', 'combine berechnet ein neues Ergebnis, sobald einer der Eingabeflows nach der ersten Emission beider eine Änderung liefert. Die UI muss so nicht selbst zwei Datenquellen koordinieren. stateIn hält anschließend das jüngste UI-Modell.', [a('kotlin/flow','Kotlin Flow auf Android'), FLOW])
lesson('bear-056', 'bear-06', 'Zustand durch copy aktualisieren.', 'Ergänze Update-Operation, Datenkopie und Negation zum Umschalten des Beispiels.', (V, 'fun toggleExample()'), [g('update','StateFlow aktualisieren','update erhält den bisherigen Wert und berechnet den nächsten.'),g('copy','Neue Modellinstanz','Die Änderung bleibt auf showExample begrenzt.'),g('!it.showExample','Umschalten','Negiere den bisherigen Boolean.')], 'MutableStateFlow.update', 'update ersetzt den State über eine Transformationsfunktion. it ist das bisherige TopicUi. Die Lambda sollte keine Seiteneffekte enthalten, weil sie bei konkurrierenden Aktualisierungen mehrmals ausgewertet werden kann.', [k('data-classes'), FLOW])
lesson('bear-057', 'bear-06', 'Eine Coroutine für die Erfassung.', 'Ergänze Scope und Repository-Aufruf in BearViewModel.capture.', (V, 'fun capture(text:', '\n    }'), [g('viewModelScope.launch','Coroutine starten','Die Coroutine soll zum ViewModel gehören.'),g('c.thoughts.capture(text)','Gedanken speichern','Der Container stellt das ThoughtRepository bereit.')], 'Vom UI-Ereignis zum Repository', 'capture ist die Grenze zwischen UI-Callback und suspendierender Arbeit. launch startet die Coroutine. Anschließend merkt sich Bear gesehene Hinweise. Das Repository ist zuständig für den lokalen Datensatz und das Einplanen des Transfers.', [CORO, a('topic/architecture/data-layer','Datenebene')])
lesson('bear-058', 'bear-06', 'Eintrag wechseln, alten Flow ablösen.', 'Ergänze den Wechseloperator, den leeren Flow und die Kombination der vier Datenquellen.', (V, 'val entry: StateFlow<EntryUi?>', '}.stateIn(viewModelScope, SharingStarted.Eagerly, null)'), [g('flatMapLatest','Auf die aktuelle ID wechseln','Ein neuer äußerer Wert löst das Sammeln des bisherigen inneren Flows ab.'),g('flowOf(null)','Kein Eintrag','Auch ohne ID wird ein Flow benötigt.'),g('combine','Vier Quellen verbinden','Thema, Gedanke, Edits und Einstellungen bilden zusammen EntryUi.')], 'flatMapLatest', 'Die gewählte ID bestimmt, welche Datensätze Bear beobachtet. flatMapLatest beendet die Sammlung des alten inneren Flows bei einem ID-Wechsel. combine baut danach die Ansicht aus dem aktuellen Thema, Gedanken, offenen Edit und Einstellungen.', [a('kotlin/flow','Kotlin Flow'), FLOW])
lesson('bear-059', 'bear-06', 'Entwürfe bei Live-Updates schützen.', 'Ergänze den lokalen Abbruch, die Konvertierung zum Entwurf und die Bedingung für einen seit der Basis unveränderten Entwurf.', (V, 'entry.collect { e ->', 'draftBase = fresh'), [g('return@collect','Noch kein Eintrag','Nur diesen Collector-Aufruf verlassen.'),g('e.toDraft()','Aktuellen Entwurf ableiten','Die Extension erstellt ein EntryDraft.'),g('d == draftBase','Unbearbeitet erkennen','Wenn Entwurf und bisherige Basis gleich sind, wurde lokal nichts geändert.')], 'Serverzustand und Eingabezustand', 'Der Flow kann während des Tippens neue Daten liefern. Bear ersetzt den Entwurf nur beim Wechsel oder wenn er nicht bearbeitet wurde. draftBase hält die letzte Datenbasis. So überschreibt ein gewöhnliches Live-Update nicht einfach die laufende Eingabe.', [k('equality'), a('develop/ui/compose/state-hoisting','Zustandseigentümer')])
lesson('bear-060', 'bear-06', 'Navigation als Zustand.', 'Rekonstruiere den speicherbaren Zustand für Ziel und Eintrags-ID sowie den Effekt für ein neues Rundensignal.', (A, 'var dest by rememberSaveable', 'LaunchedEffect(openRoundSignal)'), [g('mutableStateOf(Destination.Home)','Startziel','Die Navigation beginnt bei Home.'),g('mutableStateOf<String?>(null)','Optionale Eintrags-ID','Ohne gewählten Eintrag ist die ID null.'),g('dest = Destination.Round','Rundensignal verarbeiten','Ändere im Effekt das Ziel, wenn das Signal positiv ist.')], 'Navigation und Wiederherstellung', 'MainScreens verwaltet diese einfache Navigation selbst. rememberSaveable bewahrt kleine Navigationswerte. Ein LaunchedEffect reagiert auf openRoundSignal. Die Lösung erklärt die tatsächliche Bear-Struktur, ohne zusätzlich eine Navigation-Bibliothek vorauszusetzen.', [STATE, a('develop/ui/compose/side-effects','Effekte')])

# 61–70: real schema, settings and object graph.
lesson('bear-061', 'bear-07', 'Ein Gedanke wird zur Tabelle.', 'Ergänze die Room-Annotation, den Tabellennamen als String und den Primärschlüssel-Marker.', (D, '@Entity(tableName = "thoughts")', '\n)'), [g('@Entity','Tabelle deklarieren','Room nutzt @Entity.'),g('"thoughts"','Tabellenname','Der echte Name ist thoughts, als Kotlin-String.'),g('@PrimaryKey','Eindeutige ID','Die ID unterscheidet die Datensätze.')], 'ThoughtEntity', 'Bear schreibt einen Gedanken zunächst in diese lokale Tabelle. Zustand und mögliche Linear-Kennung liegen im selben Modell. @PrimaryKey bezieht sich auf id; diese UUID wird später auch zur Vermeidung doppelter Remote-Issues genutzt.', [a('training/data-storage/room/defining-data','Entities')])
lesson('bear-062', 'bear-07', 'Neue Gedanken zuerst beobachten.', 'Ergänze die DAO-Annotation, den gesamten SQL-String und den beobachtbaren Rückgabetyp.', (D, '@Dao\ninterface ThoughtDao', 'fun observeAll(): Flow<List<ThoughtEntity>>'), [g('@Dao','DAO markieren','Das Interface beschreibt Datenzugriff.'),g('"SELECT * FROM thoughts ORDER BY createdAt DESC"','Sortierte SQL-Abfrage','Lies thoughts absteigend nach createdAt; gib den Kotlin-String mit Anführungszeichen an.'),g('Flow<List<ThoughtEntity>>','Beobachtbare Liste','Der Flow liefert Listen von ThoughtEntity.')], 'SQL in Kotlin', 'Der Query-Inhalt ist SQL innerhalb eines Kotlin-String-Literals. DESC bedeutet absteigend. Room erzeugt die DAO-Implementierung und kann die Abfrage gegen das Schema prüfen. Änderungen an beobachteten Tabellen führen zu neuen Abfrageergebnissen.', [a('training/data-storage/room/accessing-data','DAOs')])
lesson('bear-063', 'bear-07', 'Ein Modell einfügen oder aktualisieren.', 'Ergänze die Room-Annotation und den Parametertyp für TopicDao.upsert.', (D, '@Upsert\n    suspend fun upsert(topic:'), [g('@Upsert','Schreiben','Upsert fügt ein oder aktualisiert anhand des Schlüssels.'),g('TopicEntity','Themenmodell','Der Parameter ist ein Datensatz aus topics.')], 'Upsert', 'TopicDao verwendet suspendierende Schreibmethoden. Upsert verbindet Einfügen und Aktualisieren für die angegebene Entity. Der Primärschlüssel bestimmt die Identität; eine neue Kopie des Kotlin-Objekts bedeutet nicht automatisch eine neue Tabellenzeile.', [ROOM])
lesson('bear-064', 'bear-07', 'Listen für Room serialisieren.', 'Ergänze die Serialisierungs- und Deserialisierungsmethoden für Bears Satzliste.', (D, 'class Converters {', '\n}'), [g('encodeToString','Liste zu JSON','Die Liste wird in einen String serialisiert.'),g('decodeFromString','JSON zur Liste','Die Rückgabetypangabe liefert hier List<String>.')], 'TypeConverter', 'SQLite hat keinen List<String>-Spaltentyp. Bear wandelt die Liste über Kotlin Serialization in JSON und zurück. Die TypeConverter-Annotationen verbinden diese Methoden mit Room. Das Format gehört zur Persistenzgrenze und darf nicht beiläufig geändert werden.', [a('training/data-storage/room/referencing-data','Room-Typkonverter'), k('serialization')])
lesson('bear-065', 'bear-07', 'Das Datenbankschema versionieren.', 'Ergänze die Datenbank-Basisklasse und die automatische Migration von Version 1 nach 2.', (D, '@Database(', 'abstract fun thoughts(): ThoughtDao'), [g('AutoMigration(from = 1, to = 2)','Migration','Die alte und neue Schemaversion müssen ausdrücklich benannt werden.'),g('RoomDatabase()','Room-Basisklasse','BearDatabase erbt von RoomDatabase.')], 'Schema und Migration', 'Bear exportiert sein Room-Schema und deklariert eine AutoMigration. Das ist eine Beschreibung des vorhandenen Übergangs. Nicht jede künftige Schemaänderung lässt sich automatisch migrieren; Datenmigrationen brauchen eigene Prüfung.', [a('training/data-storage/room/migrating-db-versions','Migrationen')])
lesson('bear-066', 'bear-07', 'Einstellungen an Context binden.', 'Ergänze die Extension-Eigenschaft, die Delegation und den DataStore-Erzeuger.', (S, 'private val Context.store by preferencesDataStore'), [g('Context','Empfängertyp','Die Extension hängt am Android-Context.'),g('by','Delegation','Der Delegate liefert die Store-Instanz.'),g('preferencesDataStore','Preferences-DataStore','Die Top-Level-Delegation vermeidet neue Instanzen bei jedem Zugriff.')], 'DataStore-Delegate', 'Context.store ist eine private Extension-Eigenschaft. Der Delegate kapselt die Erstellung von Preferences DataStore mit dem Namen bear. Dort liegen kleine Einstellungen; Gedanken und Themen gehören dagegen in Room.', [DATA, k('delegated-properties')])
lesson('bear-067', 'bear-07', 'Den Namen dauerhaft ändern.', 'Ergänze die atomare DataStore-Operation und die Zuweisung zum passenden Schlüssel.', (S, 'suspend fun setBearName(name:'), [g('edit','Preferences ändern','edit liefert MutablePreferences im Block.'),g('it[K.bearName] = name','Neuen Namen setzen','Verwende den typisierten Schlüssel und den Parameter name.')], 'Preferences schreiben', 'DataStore verarbeitet Änderungen über edit. K.bearName wurde mit stringPreferencesKey erzeugt. Die Funktion ist suspendierend, damit der Aufrufer die asynchrone Speicherung respektieren kann.', [DATA])
lesson('bear-068', 'bear-07', 'Ein einmaliger Stand aus einem Flow.', 'Ergänze die Flow-Operation, die den ersten Einstellungswert liest und die Sammlung danach beendet.', (S, 'suspend fun current(): BearSettings'), [g('first()','Einmaliger Snapshot','first liefert die erste Emission und beendet diese Sammlung.')], 'Snapshot oder dauerhafte Beobachtung', 'settings ist ein Flow. current dient Operationen, die für einen Vorgang einen Einstellungsstand brauchen. first wartet bei Bedarf auf den ersten Wert. Die UI beobachtet dagegen langfristig Änderungen.', [a('kotlin/flow','Flow'), DATA])
lesson('bear-069', 'bear-07', 'Abhängigkeiten ohne DI-Framework.', 'Rekonstruiere die Erzeugung von Datenbank, Gedanken-Repository und Scheduler im AppContainer.', ('BearApp.kt', 'class AppContainer(context:', 'val reliability = Reliability(context)'), [g('BearDatabase.create(context)','Datenbank erzeugen','Die Factory baut die lokale Room-Datenbank.'),g('ThoughtRepository(context, db, edits)','Gedanken-Repository','Es benötigt Context, Datenbank und EditQueue.'),g('RoundScheduler(context, db, settings)','Runden-Scheduler','Die Zeitplanung nutzt Datenbank und Einstellungen.')], 'Manuelle Dependency Injection', 'Bear verdrahtet seine Abhängigkeiten ausdrücklich in AppContainer. Die Konstruktoren zeigen, wer welchen Dienst braucht. Das ist bereits Dependency Injection, auch ohne Framework. Nicht jede Klasse sollte deshalb selbst neue Datenbanken erzeugen.', [a('training/dependency-injection/manual','Manuelle Dependency Injection')])
lesson('bear-070', 'bear-07', 'Eine Factory für das ViewModel.', 'Ergänze den Factory-Builder, den Initialisierungsblock und den Cast auf Bears Application.', (V, 'companion object {', '\n    }'), [g('viewModelFactory','Factory-DSL','Der Builder gehört zu AndroidX Lifecycle.'),g('initializer','ViewModel erstellen','Dieser Block liefert die Instanz.'),g('this[APPLICATION_KEY] as BearApp','Application aus CreationExtras','Lies die Application und verwende den BearApp-Typ.')], 'Factory und Application', 'Die Factory stellt den AppContainer bereit, wenn Android ein BearViewModel anfordert. APPLICATION_KEY stammt aus Lifecycle-CreationExtras. as ist ein Cast und schlägt fehl, falls der erwartete Typ nicht vorliegt; die App-Konfiguration muss dazu passen.', [a('topic/libraries/architecture/viewmodel/viewmodel-factories','ViewModel-Factories')])

# 71–80: persistent and asynchronous paths; longer expressions.
lesson('bear-071', 'bear-08', 'Zuerst sicher auf dem Telefon.', 'Rekonstruiere UUID-Erzeugung, lokalen Insert und Einplanen des Transfers in ThoughtRepository.capture.', (Q, 'suspend fun capture(text:', '\n    }'), [g('UUID.randomUUID().toString()','Stabile lokale Identität','Erzeuge die UUID einmal, bevor später ein Netzwerkaufruf beginnt.'),g('db.thoughts().insert(ThoughtEntity(id, text.trim(), System.currentTimeMillis(), ThoughtState.Local))','Lokal schreiben','Speichere ID, bereinigten Text, Zeitpunkt und lokalen Zustand.'),g('enqueueSend(id)','Transfer einplanen','Erst nach dem lokalen Insert wird die Arbeit eingereiht.')], 'Lokal zuerst', 'Die Funktion gibt die ID zurück, nachdem der Datensatz lokal geschrieben und das Senden eingeplant wurde. Dieselbe ID begleitet Wiederholungen. Ein abgeschlossener capture-Aufruf bedeutet damit nicht, dass Linear bereits erreicht wurde.', [a('topic/architecture/data-layer/offline-first','Offline-fähige Datenebene'), WORK])
lesson('bear-072', 'bear-08', 'Ein Upload wartet auf Netzwerk.', 'Ergänze den Worker-Typ, die Netzwerkbedingung und die Backoff-Strategie.', (Q, 'private fun enqueueSend(id:', '\n    }'), [g('SendThoughtWorker','Worker-Klasse','Dieser Worker überträgt genau einen Gedanken.'),g('NetworkType.CONNECTED','Netzwerkbedingung','Ohne Verbindung soll die Übertragung warten.'),g('BackoffPolicy.EXPONENTIAL','Wiederholungsabstand','Der Backoff wächst bei weiteren Versuchen exponentiell.')], 'Constraints und Backoff', 'WorkManager speichert diese Arbeit über den aktuellen Prozess hinaus. Die Netzwerkbedingung ist eine Ausführungsbedingung, keine Erfolgsgarantie. setExpedited hat einen Quoten-Fallback; Result.retry im Worker aktiviert die Wiederholungsstrategie.', [WORK])
lesson('bear-073', 'bear-08', 'Den Upload nicht doppelt einreihen.', 'Ergänze den eindeutigen Work-Namen und die Policy, die bereits ausstehende Arbeit mit diesem Namen beibehält.', (Q, 'WorkManager.getInstance(context).enqueueUniqueWork("send-$id"'), [g('"send-$id"','Eindeutiger Name','Die Gedanken-ID wird in einen String eingesetzt.'),g('ExistingWorkPolicy.KEEP','Konfliktstrategie','KEEP behält bestehende nicht abgeschlossene Arbeit bei.')], 'Unique Work', 'Der Name bündelt Arbeit für dieselbe ID. KEEP verhindert paralleles Neueinreihen als zweite unabhängige Kette. Das ersetzt keine Idempotenz auf der API-Seite: Ein Netzwerkaufruf kann schon erfolgreich gewesen sein, obwohl seine Antwort verlorenging.', [WORK])
lesson('bear-074', 'bear-08', 'Ein suspendierbarer Worker.', 'Ergänze die Worker-Basisklasse und den Methodenmodifikator vor doWork.', (X, 'class SendThoughtWorker(', 'override suspend fun doWork(): Result {'), [g('CoroutineWorker(context, params)','Coroutine-Worker','Die Basisklasse erhält Context und WorkerParameters.'),g('override suspend','Suspendierendes Überschreiben','doWork überschreibt die suspendierende Basismethode.')], 'CoroutineWorker', 'CoroutineWorker erlaubt suspendierende Aufrufe innerhalb von doWork. Das Ergebnis sagt WorkManager, ob die Arbeit erfolgreich ist, scheitert oder wiederholt werden soll. Der aktuelle Scope muss nicht manuell durch GlobalScope ersetzt werden.', [a('topic/libraries/architecture/workmanager/advanced/coroutineworker','CoroutineWorker')])
lesson('bear-075', 'bear-08', 'Blockierendes HTTP auslagern.', 'Ergänze den Kontextwechsel und den Dispatcher um Bears synchronen HTTP-Aufruf.', (N, 'private suspend fun call(', 'val body = buildJsonObject {'), [g('withContext','Kontextwechsel','withContext wartet auf das Ergebnis des Blocks.'),g('Dispatchers.IO','Blockierende I/O-Arbeit','Der vorhandene HTTP-Client nutzt execute().')], 'suspend ist kein Threadwechsel', 'Die HTTP-Implementierung verwendet einen blockierenden Aufruf. suspend allein würde ihn nicht von Main verschieben; withContext(Dispatchers.IO) legt den Block in einen geeigneten Kontext. Dieser Kurs erläutert den vorhandenen Client, ohne damit jede Abbruch-Eigenschaft seiner HTTP-Aufrufe zu garantieren.', [CORO])
lesson('bear-076', 'bear-08', 'Eine HTTP-Antwort schließen.', 'Ergänze die Ressourcenfunktion und die zwei retryable-Werte für Authentifizierungsfehler und temporäre Serverfehler.', (N, 'response.use { r ->', 'if (r.code == 429 || r.code >= 500)'), [g('use','Ressource schließen','use schließt die Response auch bei einer Exception.'),g('false','Ungültiger Schlüssel','401/403 brauchen eine Änderung statt blindem Retry.',within='retryable = false'),g('true','Rate Limit oder Serverfehler','429 und 5xx behandelt Bear als wiederholbar.',within='retryable = true')], 'Fehler unterscheiden', 'Der Client übersetzt HTTP-Fehler in LinearException. retryable ist eine Bear-Entscheidung über Wiederholungen. response.use begrenzt die Lebensdauer der Response. Die Einteilung ersetzt kein vollständiges Backoff- oder Rate-Limit-Konzept des Dienstes.', [k('exceptions'), CORO])
lesson('bear-077', 'bear-08', 'Result.retry oder Result.failure?', 'Rekonstruiere die Zustände und WorkManager-Ergebnisse der beiden Fehlerpfade.', (X, 'if (e.retryable) {', 'Result.failure()\n            }'), [g('ThoughtState.Local','Wiederholbarer Fehler','Der Gedanke bleibt lokal und kann erneut gesendet werden.'),g('Result.retry()','Wiederholung anfordern','WorkManager soll mit Backoff wiederholen.'),g('ThoughtState.NeedsAttention','Dauerhafter Fehler','Der Nutzer muss eingreifen.'),g('Result.failure()','Arbeit beenden','Diese Ausführung soll nicht automatisch wiederholt werden.')], 'Fehler werden Zustand', 'Der lokale Gedanke bleibt in beiden Fällen erhalten. Der Worker hinterlegt zusätzlich die Fehlermeldung. Nur beim wiederholbaren Fehler fordert er einen weiteren Versuch an; andernfalls wird der Handlungsbedarf sichtbar.', [WORK, k('exceptions')])
lesson('bear-078', 'bear-08', 'Eine verlorene Antwort abfangen.', 'Ergänze die Anfrage mit derselben UUID, die Ergebnisumwandlung und das erneute Werfen des ursprünglichen Fehlers.', (X, 'val created = try {', '?: throw e\n            }'), [g('c.linear.createIssue(key, id, target, title, description)','Erstellungsaufruf','Die zuvor lokal erzeugte ID muss mitgeschickt werden.'),g('c.linear.issue(key, id)','Nachsehen bei Fehler','Suche nach genau derselben UUID.'),g('CreatedIssue(it.identifier, it.url)','Gefundenes Issue übernehmen','Bilde den gefundenen Datensatz auf das erwartete Ergebnis ab.'),g('throw e','Fehler weitergeben','Wenn auch die Suche nichts liefert, bleibt der ursprüngliche Fehler bestehen.')], 'Idempotenz über stabile Identität', 'Ein Timeout beweist nicht, dass der Server nichts angelegt hat. Der Worker versucht nach einem LinearException-Fall, die bereits verwendete ID wiederzufinden. So kann er eine verlorene Erfolgsantwort behandeln, statt sofort ein neues Issue mit neuer ID anzulegen.', [k('exceptions'), a('topic/architecture/data-layer/offline-first','Offline-first')])
lesson('bear-079', 'bear-08', 'Edits zusammenführen statt verlieren.', 'Ergänze die Zusammenführung von Titel, Blockänderung und Versionszähler in EditQueue.record.', (Q, 'suspend fun record(issueId:', '\n    }'), [g('title ?: old?.title','Titel zusammenführen','Ohne neuen Titel den bisher wartenden behalten.'),g('block || old?.block == true','Blockänderung erhalten','Eine bereits nötige Blockänderung darf nicht zurück auf false fallen.'),g('(old?.version ?: 0) + 1','Version erhöhen','Ohne Vorgänger startet die Zählung bei 1.')], 'Eine lokale Outbox', 'EditEntity sammelt noch zu sendende Änderungen pro Issue. Spätere Änderungen bauen auf dem alten Eintrag auf. Der Versionszähler hilft beim Bestätigen nach dem Upload. Die Funktion zeigt die vorhandene Implementierung; sie belegt allein keine Transaktionssicherheit konkurrierender record-Aufrufe.', [ROOM, a('topic/architecture/data-layer/offline-first','Offline-first')])
lesson('bear-080', 'bear-08', 'Nur die gesendete Version löschen.', 'Ergänze die SQL-Bedingung einschließlich Versionsvergleich und den Rückgabetyp der DAO-Operation.', (D, '@Query("DELETE FROM edits', 'suspend fun done('), [g('"DELETE FROM edits WHERE issueId = :issueId AND version = :version"','Bedingtes Löschen','Issue-ID UND Versionsnummer müssen übereinstimmen.'),g('Int','Zahl gelöschter Zeilen','Der Worker prüft später, ob genau eine Zeile gelöscht wurde.')], 'Optimistische Bestätigung', 'Während ein Edit gesendet wird, kann schon ein neuerer entstehen. Das DELETE entfernt deshalb nur die Version, die der Worker tatsächlich gelesen hat. Bei 0 gelöschten Zeilen darf er eine inzwischen aktualisierte Änderung nicht als erledigt betrachten.', [a('training/data-storage/room/accessing-data','DAO-Abfragen')])

# 81–90: domain algorithms plus executable tests from Bear.
lesson('bear-081', 'bear-09', 'Rhythmus in gültige Grenzen bringen.', 'Rekonstruiere Basisintervall, Begrenzung der ersten Grenze und Begrenzung der letzten Grenze.', (P, 'fun effectiveDays(', '\n    }'), [g('override ?: rhythm.days','Basis wählen','Ein expliziter Abstand ersetzt den Rhythmus.'),g('coerceIn(1, Rhythm.MAX_DAYS)','Untere Grenze begrenzen','Mindestens 1, höchstens MAX_DAYS.'),g('coerceIn(first, Rhythm.MAX_DAYS)','Obere Grenze begrenzen','Die obere Grenze darf nicht unter der unteren liegen.')], 'Invarianten an einer Funktionsgrenze', 'Der Faktor wird auf beide Grenzen angewandt und gerundet. Das zweite coerceIn verwendet first als Minimum, damit das Ergebnis ein geordneter Bereich bleibt. Diese Funktion kombiniert nullable Ersatzwerte, Zahlenumwandlung und Bereichsregeln.', [k('ranges'), k('numbers')])
lesson('bear-082', 'bear-09', 'Ein Zufallstag einschließlich Obergrenze.', 'Ergänze den Zufallsaufruf und die Umwandlung für plusDays.', (P, 'fun nextDueDate(', 'today.plusDays('), [g('random.nextInt(days.first, days.last + 1)','Zufallswert','nextInt verwendet eine exklusive obere Grenze.'),g('toLong()','Für plusDays konvertieren','java.time erwartet hier Long.')], 'Zufall als Parameter', 'days ist inklusiv, nextInt oben exklusiv: Deshalb steht dort last + 1. Random wird als Parameter übergeben. Tests können einen reproduzierbaren Generator liefern, während normale Aufrufe Random.Default verwenden.', [k('numbers'), FUN])
lesson('bear-083', 'bear-09', 'Wen nimmt eine Runde mit?', 'Rekonstruiere die drei Filterprädikate für wartende, festgefahrene und frisch fällige Themen.', (R, 'fun pick(topics:', 'val fresh = topics.filter'), [g('it.inRound','Wartend','Bereits in der Runde.'),g('!it.inRound && it.unhandledRounds >= STUCK_AFTER','Festgefahren','Außerhalb der Runde und mindestens an der Schwelle.'),g('!it.inRound && it.unhandledRounds < STUCK_AFTER && !it.nextDue.isAfter(today)','Frisch fällig','Nicht wartend, noch nicht festgefahren und heute oder früher fällig.')], 'Disjunkte Auswahlmengen', 'Die Kategorien hängen zusammen: Ein festgefahrenes Thema soll nicht sofort wieder als frisch fällig erscheinen. !isAfter(today) schließt heute mit ein. Die vollständige pick-Funktion ist der Kontext für die nachfolgenden Aufgaben.', [k('collection-filtering'), k('booleans')])
lesson('bear-084', 'bear-09', 'Wie viele Plätze bleiben?', 'Rekonstruiere die verbleibenden Plätze, die reguläre Auswahl und den Fallback einer Probe-Runde.', (R, 'val slots =', 'added.forEach { updates'), [g('(max - carried.size).coerceAtLeast(0)','Freie Plätze','Bereits mitgenommene Themen belegen Plätze; das Ergebnis darf nicht negativ sein.'),g('fresh.sortedWith(order).take(slots)','Neue Themen','Nach Comparator sortieren und höchstens die freien Plätze nehmen.'),g('(topics - stuck.toSet()).sortedWith(order).take(1)','Probe-Fallback','Nichts Festgefahrenes, aber bei Bedarf ein noch nicht fälliges Thema.')], 'Auswahl mit einem Sonderfall', 'Normale Runden folgen der Fälligkeit. Eine Probe darf bei leerer Auswahl dennoch ein geeignetes Thema zeigen. Der Fallback darf die zuvor ausgeschlossenen festgefahrenen Themen nicht unbemerkt zurückholen.', [k('collection-ordering'), k('collection-filtering')])
lesson('bear-085', 'bear-09', 'Der nächste fällige Tag.', 'Ergänze den Ausschlussfilter, die leere-sichere Minimumsuche und die Berechnung je Kandidat.', (R, 'fun nextDueDay(', '.minOfOrNull'), [g('filterNot','Ausschluss','Entferne Kandidaten, für die das Prädikat wahr ist.'),g('minOfOrNull','Minimum oder null','Eine leere Kandidatenliste darf null liefern.'),g('if (it.inRound) today.plusDays(1) else maxOf(it.nextDue, today)','Tag je Kandidat','Wartende frühestens morgen; sonst nicht vor heute.')], 'Aggregation und leere Mengen', 'RoundScheduler behandelt null als Fall ohne nächste Runde. minOfOrNull kombiniert Projektion und Minimum. Der Code verhindert Termine in der Vergangenheit, indem er für nicht wartende Themen maxOf mit heute verwendet.', [k('collection-aggregate'), NULL])
lesson('bear-086', 'bear-09', 'Das Widget behält seine Auswahl.', 'Rekonstruiere den vollständigen Beibehaltungs-Guard und die Zufallsauswahl ohne sofortige Wiederholung.', (W, 'fun pick(ids:', '\n    }'), [g('current != null && currentSlot == slot && current in ids','Auswahl behalten','Aktuelle ID vorhanden, Slot unverändert, ID weiterhin enthalten.'),g('ids.filter { it != current }.ifEmpty { ids }.random(random)','Andere ID wählen','Zuerst aktuelle ID ausschließen, bei leerem Ergebnis zur Ausgangsliste zurückkehren.')], 'Zustand über ein Zeitfenster stabil halten', 'Ein Widget soll nicht bei jedem Refresh einen anderen Eintrag zeigen. Solange Slot und ID gültig bleiben, liefert die Funktion current. Gibt es nur eine ID, darf sie wiederkehren. Eine leere Liste wird vorher abgefangen.', [k('collection-filtering'), FUN])
lesson('bear-087', 'bear-09', 'Vier-Stunden-Slots berechnen.', 'Ergänze die zwei Ganzzahl-Ausdrücke: Slots pro Tag und Slot innerhalb des Tages.', (W, 'fun slot(now:'), [g('(24 / HOURS)','Slots pro Tag','24 Stunden durch den Vier-Stunden-Abstand.'),g('now.hour / HOURS','Slot am Tag','Ganzzahldivision gruppiert Stunden von 0 bis 3 in denselben Slot.')], 'Diskrete Zeitabschnitte', 'toEpochDay liefert die Tagesnummer. Multiplikation mit sechs und Addition der Tages-Slotnummer ergibt eine fortlaufende lokale Slot-ID. Diese bewusst lokale Rechnung ist keine Messung exakt verstrichener UTC-Stunden bei Zeitumstellungen.', [k('numbers')])
lesson('bear-088', 'bear-09', 'Ein bestehender Test für die Rundenauswahl.', 'Rekonstruiere den echten Test: erwartete Reihenfolge und Invariante der erzeugten Updates.', (TEST+'domain/RoundSelectionTest.kt', '@Test fun bringsAtMostThreeMostOverdueFirst()', '\n    }'), [g('listOf("b", "d", "c")','Erwartete Auswahl','Die fälligen Tage sind -3, -2 und -1.'),g('it.inRound && it.unhandledRounds == 0','Invariante neuer Updates','Neu aufgenommene Themen sind in der Runde und noch nicht unbeantwortet.')], 'Verhalten statt Implementierung testen', 'Der Test erstellt Kandidaten mit relativen Fälligkeiten. Er prüft die sichtbare Reihenfolge und die Updates als beobachtbare Ergebnisse. Die Helferfunktion c steht im Originaldatei-Kontext. Ein guter Test dokumentiert eine fachliche Regel.', [a('training/testing/local-tests','Lokale Tests'), k('collection-filtering')])
lesson('bear-089', 'bear-09', 'Zufall reproduzierbar testen.', 'Ergänze den gesetzten Random-Seed und den Gleichheitsvergleich der tatsächlich gesehenen IDs.', (TEST+'domain/WidgetPickTest.kt', '@Test fun everyEntryCanComeUp()', '\n    }'), [g('Random(it)','Deterministische Seeds','Jeder Schleifendurchlauf verwendet seinen Index als Seed.'),g('assertEquals(ids.toSet(), seen)','Abdeckung der IDs','Vergleiche die vorhandenen IDs als Set mit der beobachteten Menge.')], 'Tests für zufälliges Verhalten', 'Die Auswahl bleibt im Alltag zufällig, ist hier aber mit Seeds wiederholbar. Der Test belegt für diese Stichprobe, dass jede ID vorkommt. Er beweist keine perfekte Gleichverteilung aller möglichen Generatorzustände.', [a('training/testing/local-tests','Lokale Tests'), FUN])
lesson('bear-090', 'bear-09', 'Levenshtein Schritt für Schritt.', 'Rekonstruiere Ersetzungskosten, Rekurrenz und Zeilentausch des echten Distanzalgorithmus.', (M, 'internal fun levenshtein(', '\n    }'), [g('if (a[i - 1] == b[j - 1]) 0 else 1','Kosten der Zeichenposition','Gleiche Zeichen kosten 0, unterschiedliche 1.'),g('minOf(cur[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost)','Dynamische Rekurrenz','Minimum aus Einfügen, Löschen und Ersetzen.'),g('val t = prev; prev = cur; cur = t','Arbeitszeilen tauschen','Die vorige Zeile wird durch die berechnete ersetzt; das Array wird wiederverwendet.')], 'Dynamische Programmierung', 'SentenceMatcher braucht nur die aktuelle und vorige Matrixzeile. Indizes beginnen bei 1, die Strings bei 0. Der Tausch spart eine neue Array-Allokation pro Zeile. Die drei Übergänge repräsentieren Editieroperationen auf Präfixen.', [k('arrays'), k('control-flow')])

# 91–100: capstones. Missing expressions and complete blocks, not merely keyword quizzes.
lesson('bear-091', 'bear-10', 'Werkstatt: einen Namen bereinigen.', 'Rekonstruiere Bears vollständige Bereinigungskette: Rand-Leerraum entfernen, innere Leerraumfolgen vereinheitlichen, Länge begrenzen und leeres Ergebnis als null liefern.', (S, 'fun clean(input:', 'input.trim().replace'), [g('input.trim()','Rand-Leerraum entfernen','Beginne mit dem Eingabetext und trim.'),g(r'replace(Regex("\\s+"), " ")','Innere Leerraumfolgen','Achte auf das doppelte Backslash-Escaping im Kotlin-String.'),g('take(MAX_LENGTH).trim().ifEmpty { null }','Begrenzen und leeres Ergebnis behandeln','Nach dem Abschneiden kann am Ende wieder ein Leerzeichen stehen.')], 'Eine ganze Transformation lesen', 'Diese kurze Funktion verbindet String-Operationen, Regex-Escaping, eine Konstante und Nullable-Rückgabe. Die Reihenfolge zählt: Das zweite trim entfernt Rand-Leerraum, der erst durch das Kürzen entstanden ist. Es handelt sich um Bears konkrete Namensregel.', [k('strings'), NULL])
lesson('bear-092', 'bear-10', 'Werkstatt: Text und Beschreibung aufteilen.', 'Rekonstruiere ThoughtText.split. Der Titel stammt aus der ersten Zeile; zu langer Text soll nicht still verloren gehen.', (Q, 'fun split(text:', '\n    }'), [g('text.trim()','Eingabe bereinigen','Behalte den vollständigen bereinigten Text für die Beschreibung.'),g('trimmed.lineSequence().first().trim()','Erste Zeile','Lies nur die erste Zeile für den Titel.'),g('firstLine.take(MAX_TITLE).substringBeforeLast(\' \').ifBlank { firstLine.take(MAX_TITLE) }','Titel sinnvoll kürzen','Suche nach dem Abschneiden eine Wortgrenze; nutze bei leerem Ergebnis den harten Schnitt.'),g('trimmed != title','Beschreibung nötig','Der Titel muss den gesamten bereinigten Text abdecken, sonst bleibt eine Beschreibung nötig.'),g('title to if (needsDescription) trimmed else null','Pair zurückgeben','Links der Titel, rechts gegebenenfalls der vollständige Text.')], 'Eine verlustarme Modellgrenze', 'Der Titel ist begrenzt, die Beschreibung bewahrt bei Bedarf den gesamten Text. to erzeugt ein Pair. Die Funktion ist reine Logik und eignet sich für Tests, bevor irgendein Netzwerkaufruf stattfindet.', [k('strings'), FUN])
lesson('bear-093', 'bear-10', 'Werkstatt: Bear-Block aktualisieren.', 'Rekonstruiere writeInto, ohne Text außerhalb des Bear-Blocks anzutasten. Beachte die drei Fälle: vorhandener Block, leere Beschreibung und Anhängen.', (B, 'fun writeInto(', '\n        }'), [g(r'"```bear\n${block.render()}\n```"','Eingezäunter Block','Im Kotlin-String müssen Zeilenumbrüche als \\n geschrieben werden.'),g('description.orEmpty()','Optionale Beschreibung','null wird zum leeren String.'),g('current.replaceRange(found.range, fencedBlock)','Vorhandenen Bereich ersetzen','Ersetze nur den Match-Bereich.'),g(r'current.trimEnd() + "\n\n" + fencedBlock','Neuen Block anhängen','Zwei escaped Zeilenumbrüche trennen Beschreibung und Block.')], 'Strukturierte Daten in freiem Text', 'Bear bearbeitet gezielt einen markierten Teil einer Linear-Beschreibung. Ein vorhandener Block wird ersetzt, sonst wird angehängt. Diese Grenze schützt den restlichen Text. Die Strings enthalten echte Kotlin-Escapes, keine tatsächlichen Zeilenumbrüche innerhalb gewöhnlicher Anführungszeichen.', [k('strings'), NULL])
lesson('bear-094', 'bear-10', 'Werkstatt: unvollständige Änderungen senden.', 'Rekonstruiere das Kernstück aus EditSyncWorker. Unbekannte Bear-Zeilen sollen erhalten bleiben, und nur bei einer tatsächlichen Änderung soll geschrieben werden.', (X, 'var description = issue.description', '\n                }'), [g('BearBlock.find(issue.description)?.parsed?.block','Remote-Block lesen','Finde den Block und hole sein geparstes Modell, falls vorhanden.'),g('(remote ?: BearBlock()).copy(sentences = topic.sentences, step = topic.step, interval = topic.override())','Lokal bekannte Felder übernehmen','Kopiere von remote, damit dessen extra-Zeilen erhalten bleiben.'),g('local != remote','Änderung erkennen','Datenklassen vergleichen ihre Konstruktor-Eigenschaften.'),g('BearBlock.writeInto(issue.description, local)','Beschreibung rekonstruieren','Nutze die Funktion, die den übrigen Text erhält.'),g('c.linear.updateDescription(key, id, description)','Gezielt schreiben','Nur die berechnete Beschreibung wird aktualisiert.')], 'Read-modify-write mit Grenzen', 'Dieser Pfad erhält unbekannte Zusatzzeilen aus dem gelesenen Block. Er schreibt nur bei einem Unterschied der bekannten neuen Darstellung. Das löst nicht automatisch gleichzeitige Änderungen anderer Clients zwischen Lesen und Schreiben; dafür wäre eine weitergehende Konfliktstrategie nötig.', [k('data-classes'), a('topic/architecture/data-layer/offline-first','Datenkonflikte')])
lesson('bear-095', 'bear-10', 'Werkstatt: eine Runde terminieren.', 'Rekonstruiere die zentrale Suchschleife in nextRoundAt: Starttag, frühester Zeitpunkt, zulässiger Rest und zufällige Minute. Bear soll innerhalb eines Fensters bleiben.', (P, 'fun nextRoundAt(', '\n    }'), [g('maxOf(now.toLocalDate(), dueDate)','Starttag','Plane nicht vor heute und nicht vor der Fälligkeit.'),g('if (now.isAfter(start)) now.plusMinutes(2) else start','Frühester Zeitpunkt','Im laufenden Fenster hält der Code etwas Abstand zu jetzt.'),g('earliest.isBefore(end.minusMinutes(1))','Passt noch hinein?','Vor dem Fensterende muss noch Raum bleiben.'),g('java.time.Duration.between(earliest, end).toMinutes().coerceAtLeast(1)','Zufallsspanne','Berechne Minuten bis zum Ende mit mindestens 1.'),g('earliest.plusMinutes(random.nextLong(0, span)).withSecond(0).withNano(0)','Ergebnis berechnen','Wähle einen Offset und normalisiere Sekunden/Nanosekunden.'),g('day.plusDays(1)','Nächsten Tag prüfen','Ohne passendes Fenster beginnt die Suche am Folgetag erneut.')], 'Zeit, Schleifen und fachliche Regeln', 'Die Funktion traversiert Tage und sortierte Fenster. ZoneId kommt aus now; Random ist injizierbar. Sie berechnet einen geplanten Zeitpunkt. Android-Energiesparregeln und Alarmberechtigungen entscheiden zusätzlich darüber, wann Arbeit tatsächlich laufen darf.', [k('control-flow'), a('develop/background-work/services/alarms/schedule','Android-Alarme')])
lesson('bear-096', 'bear-10', 'Werkstatt: Alarm an WorkManager übergeben.', 'Ergänze die asynchrone Receiver-Lebensdauer, den Datenblock, beide Arbeitsvarianten und den sicheren Abschluss. Es ist die echte online-plus-Fallback-Struktur aus Bear.', (Z, 'class RoundAlarmReceiver', '\n}'), [g('goAsync()','Receiver-Lebensdauer verlängern','Der Callback kehrt zurück, während die Coroutine noch arbeitet.'),g('workDataOf(RoundWorker.KEY_LOG to logId, RoundWorker.KEY_KIND to kind)','Worker-Eingaben','Beide Werte müssen an die Arbeit weitergereicht werden.'),g('Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()','Online-Bedingung','Der erste Worker soll vor der Anzeige synchronisieren können.'),g('workDataOf(RoundWorker.KEY_LOG to logId, RoundWorker.KEY_KIND to kind, RoundWorker.KEY_FALLBACK to true)','Fallback-Eingaben','Kennzeichne den Pfad ohne Netzwerkbedingung ausdrücklich.'),g('setInitialDelay(3, TimeUnit.MINUTES)','Fallback-Verzögerung','Die Verzögerung ist ein frühester Start, kein exakter Termin.'),g('pending.finish()','Receiver abschließen','Der finally-Block muss den PendingResult immer beenden.')], 'Zwei geplante Wege, ein fachliches Ergebnis', 'Bear plant onlinefähige Arbeit und einen verzögerten Offline-Fallback. finally schließt den Receiver auch bei einem Fehler. Die spätere shownAt-Prüfung ist ein Guard, aber kein atomarer Claim zwischen zwei gleichzeitig laufenden Workern. Der Ausschnitt ist vorhandener Code, kein Beweis für Exactly-once-Ausführung.', [WORK, a('guide/components/broadcasts','BroadcastReceiver')])
lesson('bear-097', 'bear-10', 'Werkstatt: eine Runde auswählen und zeigen.', 'Rekonstruiere den zweiten Teil von RoundWorker: Auswahl anwenden, leeres Ergebnis behandeln, Modelle laden und erst dann Anzeige plus Log aktualisieren.', (X, 'val selection = RoundSelection.pick', '\n        return Result.success()'), [g('RoundSelection.pick(active.map { it.candidate() }, LocalDate.now(), probe = kind == RoundKind.Probe)','Fachliche Auswahl','Überführe aktive Entities in Domain-Kandidaten; Probe zählt gesondert.'),g('active.associateBy { it.issueId }','Lookup nach ID','Updates enthalten IDs, keine ganzen Entities.'),g('it.copy(inRound = u.inRound, unhandledRounds = u.unhandledRounds)','Auswahlzustand übernehmen','Nur diese zwei Domain-Felder werden hier geändert.'),g('selection.shown.mapNotNull { c.db.topics().get(it) }','Anzuzeigende Themen laden','Fehlende Datensätze werden entfernt.'),g('Notifications.showRound(applicationContext, shown, probe = kind == RoundKind.Probe, name = settings.bearName)','Anzeige auslösen','Die Benachrichtigung bekommt Modelle, Probe-Flag und Namen.'),g('c.scheduler.scheduleNext()','Reguläre Folgerunde','Plane nur unter der sichtbaren Regular-Bedingung.',occurrence=2)], 'Domain-Entscheidung und Seiteneffekte', 'RoundSelection entscheidet ohne Android-UI. Der Worker überträgt die Ergebnisse in die Datenbank und löst die Benachrichtigung aus. Nach einem leeren Ergebnis wird ebenfalls gegebenenfalls neu geplant. Die Operationen sind im Original nicht als gemeinsame Datenbanktransaktion formuliert.', [WORK, a('topic/architecture/domain-layer','Domain-Ebene')])
lesson('bear-098', 'bear-10', 'Werkstatt: Widget-Auswahl atomar speichern.', 'Rekonstruiere PickStore.choose. Auswahl-ID und Slot sollen innerhalb derselben DataStore-Änderung geschrieben werden; ein fehlendes Ergebnis entfernt die alte ID.', (J, 'suspend fun choose(', '\n    }'), [g('context.widgetStore.edit','Atomarer Einstellungsblock','Beide Schlüssel gehören in dieselbe edit-Operation.'),g('WidgetPick.slot(now)','Zeitslot berechnen','Nutze die Domain-Funktion mit dem übergebenen Zeitpunkt.'),g('WidgetPick.pick(ids, p[idKey(widget)], p[slotKey(widget)], slot)','Auswahl treffen','Übergib IDs, bisherige ID, bisherigen Slot und neuen Slot.'),g('chosen?.let { p[idKey(widget)] = it } ?: p.remove(idKey(widget))','ID schreiben oder entfernen','Ein fehlendes Ergebnis darf keinen alten Pick stehen lassen.'),g('p[slotKey(widget)] = slot','Slot speichern','Speichere auch bei fehlendem Pick den aktuellen Slot.')], 'Zusammengehörige Werte gemeinsam ändern', 'Die Domain-Funktion berechnet, DataStore persistiert. Der edit-Block liest den alten Stand und schreibt die zusammengehörigen Schlüssel gemeinsam. chosen gibt das Ergebnis an den Aufrufer zurück. widget ist Teil des Schlüssels, damit Instanzen unabhängig bleiben.', [DATA, NULL])
lesson('bear-099', 'bear-10', 'Werkstatt: einen Live-Entwurf richtig behalten.', 'Rekonstruiere die vollständige Schutzbedingung des Bear-Collectors und den Eintragswechsel. Lies zuerst die Originaldatei, um entry, draft und draftBase zu unterscheiden.', (V, 'viewModelScope.launch {\n            entry.collect', '\n        }'), [g('entry.collect','Quelle beobachten','entry liefert die aktuell aufbereiteten Daten.'),g('e.toDraft()','Neue Datenbasis','Erzeuge aus dem aktuellen EntryUi einen frischen Entwurf.'),g('d == null || d.id != e.id || d.isTopic != e.isTopic || d == draftBase','Wann darf ersetzt werden?','Kein Entwurf, andere ID, anderer Eintragstyp oder noch nicht bearbeitet.'),g('draft.value = fresh','Entwurf ersetzen','Dieser Schreibzugriff bleibt an die sichtbare if-Bedingung gebunden.'),g('draftBase = fresh','Basis nachführen','Die Basis wird nach jedem nicht-null Eintrag aktualisiert.')], 'Mehrere Zustände mit unterschiedlichen Aufgaben', 'entry ist die Datenansicht, draft die editierbare Kopie, draftBase die zuletzt beobachtete Basis. Gleichheit der Datenklassen erkennt einen unberührten Entwurf. Diese Regel schützt gewöhnliche Live-Updates; sie ist kein vollständiger Konflikteditor für gleichzeitig geänderte einzelne Felder.', [FLOW, k('data-classes')])
lesson('bear-100', 'bear-10', 'Werkstatt: den Textvergleich vollständig verstehen.', 'Rekonstruiere progress aus SentenceMatcher: Normalisierung, leere Eingaben, Präfixdistanz, Begrenzung und gedämpfte Rückmeldung. Verbinde dabei die Regeln aus den früheren Kapiteln.', (M, 'fun progress(typed:', '\n    }'), [g('normalize(typed)','Eingabe normalisieren','Dieselbe Normalisierung wie beim vollständigen Match verwenden.'),g('normalize(target)','Ziel normalisieren','Vergleiche beide Texte in derselben Darstellung.'),g('a.isEmpty() || b.isEmpty()','Leere Werte abfangen','Sonst droht unter anderem eine Division durch null Länge.'),g('b.take(a.length)','Zielpräfix','Vergleiche während des Tippens mit dem gleich langen Zielanfang.'),g('levenshtein(a, prefix) <= maxOf(1, tolerance(target))','Auf dem richtigen Weg?','Die Präfixdistanz darf höchstens die Toleranz, mindestens aber 1 sein.'),g('(minOf(a.length, b.length).toFloat() / b.length).coerceIn(0f, 1f)','Fortschrittswert','Gleitkommadivision und Begrenzung auf 0 bis 1.'),g('Progress(if (onTrack) value else value * 0.6f, onTrack)','Ergebnis mit Rückmeldung','Abseits des Zielpfads wird der angezeigte Wert gedämpft.')], 'Eine Heuristik als ganze Funktion', 'Die Funktion kombiniert Textnormalisierung, dynamische Distanzberechnung, Längenverhältnisse und UI-Rückmeldung. Sie akzeptiert nicht automatisch den Satz: Dafür gibt es matches. Die Zahlen beschreiben Bears aktuellen Ansatz; sie sind keine Garantie für eine psychologische Wirkung.', [k('control-flow'), k('numbers'), k('strings')])
